const NET_DIAG_RATE_KINDS: usize = 1;
#[cfg(feature = "net-console")]
const NET_DIAG_STUCK_MS: u64 = 3_000;
#[cfg(feature = "net-console")]
// Network-origin NineDoor commands may enqueue multiple TCP response segments.
// Retain a bounded cursor so each later Network phase performs at most one
// flush operation without monopolising the outer event pump.
const NET_POST_DISPATCH_FLUSH_POLLS: usize = 8;
#[cfg(feature = "net-console")]
const NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS: usize = 16;
const LOCAL_SEAT_BACKEND_POLL_PASSES_PER_TURN: usize = 1;
const LOCAL_SEAT_BURST_DRAIN_PASSES_PER_TURN: usize = 4;
const LOCAL_SEAT_EMPTY_POLLS_BEFORE_YIELD: usize = 1;
const LOCAL_SEAT_OUTPUT_KEYBOARD_POLL_PASSES: usize = 1;
const LOCAL_SEAT_HDMI_PUMP_PASSES_PER_TURN: usize = 1;
/// Serial retains first service, but queued HDMI must receive one later turn
/// even when a large diagnostic keeps UART TX continuously backlogged.
const LOCAL_SEAT_HDMI_MAX_SERIAL_DEFERRALS: u8 = 4;
/// Retain a bounded burst of high-impact milestones from the single production
/// Wi-Fi boot episode plus its one-shot linked-serial transitions. The capacity
/// decouples delayed display service from driver progress without deriving
/// storage from an outer retry count.
#[cfg(feature = "kernel")]
const CYW43_BOOTSTRAP_HDMI_MILESTONE_CAPACITY: usize = 12;
/// Material frontier changes wait at least five seconds after the preceding
/// HDMI progress line; an unchanged frontier emits one liveness heartbeat at
/// most every five seconds. Both durations are measured by the ordinary event
/// timer, never by CPU loops or retained-turn counts.
#[cfg(feature = "kernel")]
const CYW43_BOOTSTRAP_HDMI_PROGRESS_MIN_INTERVAL_MS: u64 = 5_000;
#[cfg(feature = "kernel")]
const CYW43_BOOTSTRAP_HDMI_PROGRESS_HEARTBEAT_MS: u64 = 5_000;
/// Serial retains the complete single-attempt lifecycle: preflight, begin,
/// optional in-episode repair, typed failure or Gate 8 proof, and one terminal
/// result. This queue is a saturation fallback; ordinary turns drain records
/// directly through the shared physical-console queue.
#[cfg(feature = "kernel")]
const CYW43_BOOTSTRAP_SERIAL_MILESTONE_CAPACITY: usize = 20;
/// Result of preflighting one retained CYW43 proof batch, taking its explicit
/// caller-owned decision cut, and then appending the complete batch.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Cyw43BootstrapAtomicDecisionOutcome {
    /// Schema, route, or retained capacity is not yet ready; the decision
    /// callback was not invoked and no output was mutated.
    PreflightBlocked,
    /// The caller declined its final decision after successful preflight.
    DecisionDeclined,
    /// The decision committed and the complete batch was retained.
    Retained,
    /// A preflighted fixed-capacity append failed unexpectedly. The caller's
    /// decision already committed, so recovery must remain fenced.
    RetentionInvariantFailed,
}
#[cfg(feature = "net-console")]
const LOCAL_SEAT_HDMI_PUMP_PASSES_UNDER_NET_PRESSURE: usize = 1;
const LOCAL_SEAT_NET_MIRROR_INITIAL_LINES: u64 = 4;
