/// Current CYW43 generation whose level-triggered work must be resumed.
///
/// The root-wake hit cursor remains an edge-urgency hint. This identity is the
/// durable scheduler state: it survives consumption of that edge until the
/// driver publishes exact idle for the same connection generation and pair
/// epoch within the same completed physical SDIO lifetime.
#[cfg(all(feature = "kernel", feature = "net-console"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct LinkedRuntimeCyw43DurableResume {
    generation: u32,
    pair_epoch: u64,
    physical_lifetime_epoch: u32,
}

#[cfg(all(feature = "kernel", feature = "net-console"))]
impl LinkedRuntimeCyw43DurableResume {
    const fn from_snapshot(
        snapshot: crate::drivers::driver_task_net::Cyw43ServiceWorkSnapshot,
    ) -> Option<Self> {
        if !snapshot.ordinary_network_admissible() {
            return None;
        }
        Some(Self {
            generation: snapshot.generation(),
            pair_epoch: snapshot.pair_epoch(),
            physical_lifetime_epoch: snapshot.physical_lifetime_epoch(),
        })
    }

    const fn matches(
        self,
        snapshot: crate::drivers::driver_task_net::Cyw43ServiceWorkSnapshot,
    ) -> bool {
        self.generation == snapshot.generation()
            && self.pair_epoch == snapshot.pair_epoch()
            && self.physical_lifetime_epoch == snapshot.physical_lifetime_epoch()
    }
}

#[cfg(all(feature = "kernel", feature = "net-console"))]
const LINKED_RUNTIME_NETWORK_QUANTUM_MAX_TURNS: u16 =
    crate::hal::driver_task::CYW43_WIFI_DRIVER_TASK_CONTRACT
        .budget
        .max_ops_per_turn;
#[cfg(all(feature = "kernel", feature = "net-console"))]
const LINKED_RUNTIME_NETWORK_QUANTUM_DEADLINE_MS: u64 = 25;
/// Maximum elapsed time between physical-console checkpoints while one exact
/// CYW43/SDIO parent remains retained.
///
/// The checkpoint keeps the same immutable parent and priority lease, performs
/// no NIC operation, and resets only this cadence clock after Dispatch. A
/// turn-count cadence is deliberately forbidden: the linked parent can require
/// many cheap child microsteps, and rotating after every small fixed tranche
/// can spend more service turns on console probes than on packet progress.
#[cfg(feature = "net-console")]
const LINKED_RUNTIME_NETWORK_OPERATOR_CHECKPOINT_MS: u64 = 25;

/// Outcome of one serial ownership-cutover EventPump turn.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SerialLinkedRuntimeCutoverTurn {
    /// Root still owns the UART and its accepted bytes have not drained.
    DrainPending,
    /// One immutable descriptor/init/proof action ran and must resume later.
    AttachPending,
    /// The linked runtime owns the UART and its reciprocal service was proven.
    Complete,
    /// The released generation failed closed; root UART must not be reclaimed.
    Failed,
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SerialLinkedRuntimeCutoverAction {
    ServiceRootUart,
    AdvanceDescriptor,
    AdvanceLinkedRuntime,
}

#[cfg(feature = "kernel")]
const fn serial_linked_runtime_cutover_action(
    descriptor_only: bool,
    attach_failed: bool,
    root_uart_released: bool,
    root_uart_turn_due: bool,
    root_uart_drain_observed: bool,
) -> SerialLinkedRuntimeCutoverAction {
    if root_uart_released {
        SerialLinkedRuntimeCutoverAction::AdvanceLinkedRuntime
    } else if attach_failed || root_uart_turn_due {
        SerialLinkedRuntimeCutoverAction::ServiceRootUart
    } else if descriptor_only {
        SerialLinkedRuntimeCutoverAction::AdvanceDescriptor
    } else if root_uart_drain_observed {
        SerialLinkedRuntimeCutoverAction::AdvanceLinkedRuntime
    } else {
        SerialLinkedRuntimeCutoverAction::ServiceRootUart
    }
}

#[cfg(feature = "kernel")]
const fn ordinary_eventpump_serial_cutover_required(
    physical_owner_state_active: bool,
    linked_runtime_active: bool,
    attach_failed: bool,
) -> bool {
    physical_owner_state_active && !linked_runtime_active && !attach_failed
}

#[cfg(feature = "kernel")]
fn cyw43_bootstrap_serial_milestone(line: &str) -> bool {
    line.as_bytes().starts_with(b"CYW43_BOOTSTRAP_SUPERVISOR ")
        || line.as_bytes().starts_with(b"CYW43_GATE8_COMMIT ")
        || line.as_bytes().starts_with(b"CYW43_RUNTIME_RECOVERY ")
        || line.as_bytes().starts_with(b"wifi: gate 8 subgate=")
        || line.as_bytes().starts_with(b"wifi: deferred_recovery ")
        || line.as_bytes().starts_with(b"CYW43_GATE8_TERMINAL ")
        || cyw43_pair_recovery_signalled_turn(line)
        || line
            .as_bytes()
            .starts_with(b"[net-console] deferred failed detail=")
}

#[cfg(feature = "kernel")]
fn cyw43_gate8_pass_line_matches_token(line: &str, expected_token: &str) -> bool {
    line.strip_prefix("wifi: gate 8 subgate=")
        .and_then(|rest| rest.split_ascii_whitespace().next())
        == Some(expected_token)
        && line.contains(" status=pass ")
        && line.ends_with(" blocker=none")
}

#[cfg(feature = "kernel")]
fn cyw43_gate8_pass_line_identity(line: &str, expected_token: &str) -> Option<(u64, u32)> {
    if !cyw43_gate8_pass_line_matches_token(line, expected_token) {
        return None;
    }
    let mut pair_epoch = None;
    let mut generation = None;
    let mut field_count = 0;
    for field in line.split_ascii_whitespace() {
        field_count += 1;
        if let Some(value) = field.strip_prefix("pair_epoch=") {
            if pair_epoch.is_some() {
                return None;
            }
            pair_epoch = value.parse().ok();
        } else if let Some(value) = field.strip_prefix("generation=") {
            if generation.is_some() {
                return None;
            }
            generation = value.parse().ok();
        }
    }
    if field_count != 8 {
        return None;
    }
    Some((pair_epoch?, generation?))
}

#[cfg(feature = "kernel")]
fn cyw43_gate8_commit_matches_identity(
    line: &str,
    expected_pair_epoch: u64,
    expected_generation: u32,
) -> bool {
    if !line.as_bytes().starts_with(b"CYW43_GATE8_COMMIT ") {
        return false;
    }
    let mut attempt = None;
    let mut status = None;
    let mut pair_epoch = None;
    let mut generation = None;
    let mut deadline_ms = None;
    let mut console_sequence = None;
    let mut telemetry_sinks = None;
    let mut consumer = None;
    let mut field_count = 0;
    for field in line.split_ascii_whitespace().skip(1) {
        field_count += 1;
        if let Some(value) = field.strip_prefix("attempt=") {
            if attempt.is_some() {
                return false;
            }
            attempt = value.parse::<u32>().ok();
        } else if let Some(value) = field.strip_prefix("status=") {
            if status.is_some() {
                return false;
            }
            status = Some(value);
        } else if let Some(value) = field.strip_prefix("pair_epoch=") {
            if pair_epoch.is_some() {
                return false;
            }
            pair_epoch = value.parse::<u64>().ok();
        } else if let Some(value) = field.strip_prefix("generation=") {
            if generation.is_some() {
                return false;
            }
            generation = value.parse::<u32>().ok();
        } else if let Some(value) = field.strip_prefix("deadline_ms=") {
            if deadline_ms.is_some() {
                return false;
            }
            deadline_ms = value.parse::<u64>().ok();
        } else if let Some(value) = field.strip_prefix("console_seq=") {
            if console_sequence.is_some() {
                return false;
            }
            console_sequence = value.parse::<u64>().ok();
        } else if let Some(value) = field.strip_prefix("telemetry_sinks=") {
            if telemetry_sinks.is_some() {
                return false;
            }
            telemetry_sinks = Some(value);
        } else if let Some(value) = field.strip_prefix("consumer=") {
            if consumer.is_some() {
                return false;
            }
            consumer = Some(value);
        } else {
            return false;
        }
    }
    field_count == 8
        && attempt == Some(1)
        && status == Some("ready")
        && pair_epoch == Some(expected_pair_epoch)
        && generation == Some(expected_generation)
        && deadline_ms.is_some()
        && console_sequence.is_some()
        && telemetry_sinks == Some("serial+qlog+hdmi")
        && consumer == Some("data")
}

#[cfg(feature = "kernel")]
fn cyw43_runtime_service_ready_matches_identity(line: &str, expected_generation: u32) -> bool {
    if !line.as_bytes().starts_with(b"CYW43_RUNTIME_RECOVERY ") {
        return false;
    }
    let mut status = None;
    let mut generation = None;
    let mut console_sequence = None;
    let mut telemetry_sinks = None;
    let mut field_count = 0;
    for field in line.split_ascii_whitespace().skip(1) {
        field_count += 1;
        if let Some(value) = field.strip_prefix("status=") {
            if status.is_some() {
                return false;
            }
            status = Some(value);
        } else if let Some(value) = field.strip_prefix("generation=") {
            if generation.is_some() {
                return false;
            }
            generation = value.parse::<u32>().ok();
        } else if let Some(value) = field.strip_prefix("console_seq=") {
            if console_sequence.is_some() {
                return false;
            }
            console_sequence = value.parse::<u64>().ok();
        } else if let Some(value) = field.strip_prefix("telemetry_sinks=") {
            if telemetry_sinks.is_some() {
                return false;
            }
            telemetry_sinks = Some(value);
        } else {
            return false;
        }
    }
    field_count == 4
        && status == Some("ready")
        && generation == Some(expected_generation)
        && console_sequence.is_some()
        && telemetry_sinks == Some("serial+qlog+hdmi")
}

#[cfg(feature = "kernel")]
fn cyw43_bootstrap_turn_attempt_and_stage(line: &str) -> Option<(u32, &str)> {
    if !line.as_bytes().starts_with(b"CYW43_BOOTSTRAP_TURN ") {
        return None;
    }
    let mut attempt = None;
    let mut stage = None;
    for field in line.split_ascii_whitespace().skip(1) {
        if let Some(value) = field.strip_prefix("attempt=") {
            attempt = value.parse::<u32>().ok().filter(|value| *value == 1);
        } else if let Some(value) = field.strip_prefix("stage=") {
            stage = (!value.is_empty()).then_some(value);
        }
    }
    Some((attempt?, stage?))
}

#[cfg(feature = "kernel")]
fn cyw43_pair_recovery_signalled_turn(line: &str) -> bool {
    cyw43_bootstrap_turn_attempt_and_stage(line) == Some((1, "cyw43-pair-recovery-signalled"))
}

#[cfg(feature = "kernel")]
fn cyw43_bootstrap_status_resets_hdmi_progress(
    hdmi_line: &str,
    releases_console_ready: bool,
) -> bool {
    releases_console_ready
        || hdmi_line == "[drivers] WiFi bootstrap starting (single production attempt)"
        || hdmi_line == "[drivers] WiFi repairing CYW43/SDIO within the active boot episode"
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ConsoleErrorKey {
    LineTooLong,
    EmptyLine,
    InvalidVerb,
    MissingArgument,
    ValueTooLong,
    RateLimited,
    InvalidValue,
}

impl ConsoleErrorKey {
    const fn from_error(err: &ConsoleError) -> Self {
        match err {
            ConsoleError::LineTooLong => Self::LineTooLong,
            ConsoleError::EmptyLine => Self::EmptyLine,
            ConsoleError::InvalidVerb => Self::InvalidVerb,
            ConsoleError::MissingArgument(_) => Self::MissingArgument,
            ConsoleError::ValueTooLong(_) => Self::ValueTooLong,
            ConsoleError::RateLimited(_) => Self::RateLimited,
            ConsoleError::InvalidValue(_) => Self::InvalidValue,
        }
    }
}

const fn console_parse_error_repeat_checkpoint(count: u16) -> bool {
    count != 0 && (count & (count - 1)) == 0
}

