    fn wifi_diag_deferred_recovery_identity_line(
        recovery: crate::drivers::driver_task_net::Cyw43DeferredRecoveryDiagnostic,
    ) -> HeaplessString<DEFAULT_LINE_CAPACITY> {
        format_message(format_args!(
            "wifi: deferred_recovery identity generation={} owner_generation={} ticket={} completion_detail=0x{:04x} completion_result=0x{:08x} completion_sequence={} turn={}",
            recovery.generation,
            recovery.owner_generation,
            recovery.ticket_id,
            recovery.completion_detail,
            recovery.completion_result,
            recovery.completion_sequence,
            recovery.turn_id,
        ))
    }

    #[cfg(feature = "kernel")]
    fn wifi_diag_deferred_recovery_completion_line(
        recovery: crate::drivers::driver_task_net::Cyw43DeferredRecoveryDiagnostic,
    ) -> HeaplessString<DEFAULT_LINE_CAPACITY> {
        let cause = if !recovery.terminal_observed {
            "none-unobserved"
        } else {
            Self::wifi_deferred_recovery_completion_cause(recovery.completion_result)
        };
        let status = if !recovery.terminal_observed {
            "unobserved"
        } else if recovery.subphase == "sdio-engine-init-failed" {
            crate::drivers::driver_task_net::sdio_engine_init_detail_status(
                recovery.completion_detail,
            )
            .unwrap_or("fault")
        } else {
            "runtime-terminal"
        };
        format_message(format_args!(
            "wifi: deferred_recovery completion observed={} sequence={} detail=0x{:04x} result=0x{:08x} status={} cause={}",
            Self::yes_no(recovery.terminal_observed),
            recovery.completion_sequence,
            recovery.completion_detail,
            recovery.completion_result,
            status,
            cause,
        ))
    }

