    #[cfg(feature = "kernel")]
    fn wifi_driver_task_progress_test_guard() -> WifiDriverTaskProgressTestGuard {
        let guard = WIFI_DRIVER_TASK_PROGRESS_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        clear_wifi_driver_task_test_state();
        // Scheduling tests model the post-bootstrap EventPump. The completed
        // lifetime is a prerequisite now, not an incidental global leftover.
        crate::drivers::driver_task_net::set_cyw43_service_physical_lifetime_epoch_test_override(
            Some(1),
        );
        crate::hal::driver_task::test_set_sdio_clock_snapshot_override(Some(
            test_sdio_clock_snapshot(1),
        ));
        WifiDriverTaskProgressTestGuard { _guard: guard }
    }

    struct TestTimer {
        ticks: HeaplessVec<TickEvent, 8>,
        index: usize,
    }

    impl TestTimer {
        fn single(tick: TickEvent) -> Self {
            let mut ticks = HeaplessVec::new();
            let _ = ticks.push(tick);
            Self { ticks, index: 0 }
        }

        fn repeated(count: usize, spacing_ms: u64) -> Self {
            let mut ticks = HeaplessVec::new();
            for i in 0..count {
                let _ = ticks.push(TickEvent {
                    tick: (i + 1) as u64,
                    now_ms: (i as u64 + 1) * spacing_ms,
                });
            }
            Self { ticks, index: 0 }
        }
    }

    impl TimerSource for TestTimer {
        fn poll(&mut self, _now_ms: u64) -> Option<TickEvent> {
            if self.index >= self.ticks.len() {
                return None;
            }
            let tick = self.ticks[self.index];
            self.index += 1;
            Some(tick)
        }
    }

    #[test]
    fn diagnostic_formatting_marks_overflow_without_splitting_utf8() {
        let long = "é".repeat(DEFAULT_LINE_CAPACITY);
        let rendered = format_message(format_args!("prefix={long}"));

        assert!(
            rendered.ends_with(DIAGNOSTIC_TRUNCATION_MARKER),
            "{rendered}"
        );
        assert!(rendered.len() < DEFAULT_LINE_CAPACITY);
        assert!(core::str::from_utf8(rendered.as_bytes()).is_ok());
    }

