    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_diag_decodes_sdio_transfer_failure_result() {
        type TestPump<'a> = EventPump<
            'a,
            LoopbackSerial<16>,
            TestTimer,
            NullIpc,
            TicketTable<4>,
            4,
            4,
            DEFAULT_LINE_CAPACITY,
        >;

        let response_r5 = (5 << 24) | 0x0100;
        assert_eq!(
            TestPump::wifi_sdio_transfer_failure_stage(response_r5),
            "response"
        );
        assert_eq!(
            TestPump::wifi_sdio_transfer_failure_status(response_r5),
            0x0100
        );
        assert_eq!(TestPump::wifi_sdio_transfer_failure_r5(response_r5), 0x0100);

        let data_wait = (3 << 24) | 0x0000_8000;
        assert_eq!(
            TestPump::wifi_sdio_transfer_failure_stage(data_wait),
            "data-wait"
        );
        assert_eq!(TestPump::wifi_sdio_transfer_failure_r5(data_wait), 0);
        assert_eq!(
            TestPump::wifi_sdio_transfer_failure_stage((6 << 24) | 0x2),
            "post-issue-quiesce"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_diag_preserves_post_release_gate_proof_and_decodes_no_rframe() {
        type TestPump<'a> = EventPump<
            'a,
            LoopbackSerial<16>,
            TestTimer,
            NullIpc,
            TicketTable<4>,
            4,
            4,
            DEFAULT_LINE_CAPACITY,
        >;

        let fault = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-control-txglomalign",
            op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 36,
            total_len: 36,
            control_cmd: 263,
            control_id: 1,
            control_header_mode: "plain",
            control_response_len: 0,
            detail: 0x530b,
            reason: "cyw43-control-exchange",
            result: 0x4303_0000,
        };

        assert_eq!(TestPump::wifi_runtime_fault_gate(fault), 8);
        assert!(TestPump::wifi_runtime_fault_implies_firmware_ready(fault));
        assert!(TestPump::wifi_runtime_fault_implies_firmware_uploaded(
            fault
        ));
        assert!(TestPump::wifi_runtime_fault_implies_hal_power_ready(fault));
        assert_eq!(
            TestPump::wifi_control_exchange_timeout_reason(fault.result),
            "no-rframe"
        );
        assert_eq!(
            TestPump::wifi_control_exchange_timeout_tx_state(fault.result),
            "submitted"
        );
        let rendered = TestPump::wifi_diag_cyw43_fault_control(fault, true);
        assert!(rendered.contains("pre_tx_drain=no"), "{rendered}");
        assert!(rendered.contains("timeout_reason=no-rframe"), "{rendered}");
        assert!(rendered.contains("timeout_value=0"), "{rendered}");
        assert!(rendered.contains("tx_state=submitted"), "{rendered}");

        let nonmatching = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            result: 0x4308_0001,
            ..fault
        };
        assert_eq!(
            TestPump::wifi_control_exchange_timeout_reason(nonmatching.result),
            "nonmatching-reply"
        );
        assert_eq!(
            TestPump::wifi_control_exchange_timeout_tx_state(nonmatching.result),
            "submitted"
        );
        let nonmatching_rendered = TestPump::wifi_diag_cyw43_fault_control(nonmatching, true);
        assert!(
            nonmatching_rendered.contains("timeout_reason=nonmatching-reply"),
            "{nonmatching_rendered}"
        );
        assert!(
            nonmatching_rendered.contains("timeout_value=1"),
            "{nonmatching_rendered}"
        );
        assert!(
            nonmatching_rendered.contains("tx_state=submitted"),
            "{nonmatching_rendered}"
        );

        let owner_mismatch = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            detail: crate::hal::driver_task::DriverTaskFaultCode::RejectedCommand.as_u16(),
            reason: "cyw43-control-owner-mismatch",
            result: 0x5344_0004,
            ..fault
        };
        let owner_mismatch_summary = TestPump::wifi_diag_cyw43_fault_summary(owner_mismatch, true);
        assert!(
            owner_mismatch_summary.contains("reason=cyw43-control-owner-mismatch"),
            "{owner_mismatch_summary}"
        );
    }

