    #[test]
    fn console_ready_announcement_enables_local_seat_attach() {
        let driver = LoopbackSerial::<8192>::new();
        let serial = SerialPort::<_, 8192, 8192, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::single(TickEvent {
            tick: 1,
            now_ms: 10,
        });
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "pass").unwrap();
        let mut audit = AuditLog::new();
        let mut local_seat = LocalSeatRuntime::new(crate::local_seat::LocalSeatStatus {
            keyboard_device: "usb-kbd0",
            display_device: "hdmi0",
            line_bytes: 32,
            buffer_lines: 4,
        });
        let mut pump =
            EventPump::new(serial, timer, ipc, store, &mut audit).with_local_seat(&mut local_seat);

        pump.start_cli();
        let emitted = pump.serial_mut().driver_mut().drain_tx();
        let transcript = core::str::from_utf8(emitted.as_slice()).unwrap();

        assert!(transcript.contains(CONSOLE_BANNER));
        assert!(!transcript.contains(CONSOLE_PROMPT));
        assert_eq!(pump.metrics().local_seat_output_keyboard_polls, 0);
        #[cfg(all(feature = "kernel", feature = "usb"))]
        assert!(!pump.post_prompt_local_seat_attach_pending_for_test());
        assert!(!pump.local_seat.as_ref().unwrap().root_console_ready());

        pump.announce_console_ready();
        let ready_emitted = pump.serial_mut().driver_mut().drain_tx();
        let ready_transcript = core::str::from_utf8(ready_emitted.as_slice()).unwrap();
        assert!(ready_transcript.contains("Cohesix console ready"));
        assert!(ready_transcript.contains("Commands:"));
        assert!(ready_transcript.ends_with(CONSOLE_PROMPT));
        #[cfg(all(feature = "kernel", feature = "usb"))]
        assert!(pump.post_prompt_local_seat_attach_pending_for_test());
        drop(pump);
        assert!(local_seat.root_console_ready());
        assert!(local_seat
            .mirrored_lines_snapshot()
            .iter()
            .any(|line| line.as_str() == "Cohesix serial console ready"));
        assert!(!local_seat
            .mirrored_lines_snapshot()
            .iter()
            .any(|line| line.as_str() == CONSOLE_PROMPT));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_hdmi_progress_cadence_uses_virtual_milliseconds_and_material_frontiers() {
        use crate::drivers::driver_task_net::Cyw43BootstrapDisplayFrontier as Frontier;

        let mut cadence = Cyw43BootstrapHdmiProgressCadence::new();
        cadence.observe(1, Frontier::LinkedRuntimes, 1_000);
        assert_eq!(cadence.due(5_999), None);
        assert_eq!(cadence.due(6_000), Some((Frontier::LinkedRuntimes, false)));
        cadence.record_emitted(Frontier::LinkedRuntimes, 6_000);

        cadence.observe(1, Frontier::FirmwareUpload, 6_001);
        assert_eq!(cadence.due(10_999), None);
        assert_eq!(cadence.due(11_000), Some((Frontier::FirmwareUpload, false)));
        cadence.record_emitted(Frontier::FirmwareUpload, 11_000);
        // Keep the production five-second contract explicit rather than
        // deriving this boundary from the implementation constant.
        assert_eq!(cadence.due(15_999), None);
        assert_eq!(cadence.due(16_000), Some((Frontier::FirmwareUpload, true)));

        cadence.observe(2, Frontier::CardPath, 30_000);
        assert_eq!(cadence.due(34_999), None);
        assert_eq!(cadence.due(35_000), Some((Frontier::CardPath, false)));
    }

    #[cfg(all(feature = "kernel", feature = "net-console"))]
    #[test]
    fn cyw43_network_ready_requires_dhcp_bound_ip_and_listener() {
        let mut status = NetStatusReport::default();
        let mut counters = NetCounters {
            wifi_connection_generation: 17,
            ..NetCounters::default()
        };
        assert_eq!(
            cyw43_network_ready_hdmi_state(&status, false),
            Cyw43NetworkReadyHdmiState::WaitingForNetworkStack
        );
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, false, 17,
        ));

        status.active_driver = "cyw43";
        status.active_interface = "wifi";
        status.address_source = "dhcp-pending";
        status.dhcp_phase = "selecting";
        assert_eq!(
            cyw43_network_ready_hdmi_state(&status, false),
            Cyw43NetworkReadyHdmiState::WaitingForDhcp
        );
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, false, 17,
        ));
        status.dhcp_phase = "requesting";
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, false, 17,
        ));

        status.address_source = "dhcp-lease";
        status.dhcp_phase = "bound";
        assert_eq!(
            cyw43_network_ready_hdmi_state(&status, true),
            Cyw43NetworkReadyHdmiState::WaitingForDhcp
        );
        status.ip.push_str("192.168.86.154").unwrap();
        assert_eq!(
            cyw43_network_ready_hdmi_state(&status, false),
            Cyw43NetworkReadyHdmiState::WaitingForTcpListener
        );
        assert_eq!(
            cyw43_network_ready_hdmi_state(&status, true),
            Cyw43NetworkReadyHdmiState::Ready
        );
        assert!(
            net_status_has_cyw43_boot_service_ready(&status, counters, true, 17),
            "bootstrap service readiness requires listener admission, not a prior TCP session",
        );
        assert!(
            !status.tcp_ready,
            "the first host TCP session cannot be required before bootstrap Ready",
        );
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, true, 18,
        ));
        counters.wifi_connection_generation = 18;
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, true, 17,
        ));
        status.active_driver = "bcmgenet-v5";
        status.active_interface = "wired";
        assert!(!net_status_has_cyw43_boot_service_ready(
            &status, counters, true, 18,
        ));
        assert!(cyw43_runtime_service_ready_matches_identity(
            "CYW43_RUNTIME_RECOVERY status=ready generation=18 console_seq=9 telemetry_sinks=serial+qlog+hdmi",
            18,
        ));
        assert!(!cyw43_runtime_service_ready_matches_identity(
            "CYW43_RUNTIME_RECOVERY status=ready generation=18 console_seq=9 telemetry_sinks=serial+qlog+hdmi",
            17,
        ));
    }

    #[cfg(all(feature = "kernel", feature = "net-console"))]
    #[test]
    fn cyw43_network_wait_progress_refreshes_on_frontier_and_heartbeat() {
        let mut cadence = Cyw43NetworkReadyHdmiProgressCadence::new();
        cadence.begin(17, 1_000);
        cadence.observe(Cyw43NetworkReadyHdmiState::WaitingForDhcp);
        assert_eq!(cadence.due(5_999), None);
        assert_eq!(
            cadence.due(6_000),
            Some((Cyw43NetworkReadyHdmiState::WaitingForDhcp, false))
        );
        cadence.record_emitted(Cyw43NetworkReadyHdmiState::WaitingForDhcp, 6_000);

        cadence.observe(Cyw43NetworkReadyHdmiState::WaitingForTcpListener);
        assert_eq!(cadence.due(10_999), None);
        assert_eq!(
            cadence.due(11_000),
            Some((Cyw43NetworkReadyHdmiState::WaitingForTcpListener, false,))
        );
        cadence.record_emitted(Cyw43NetworkReadyHdmiState::WaitingForTcpListener, 11_000);
        // DHCP/listener wait feedback uses the same explicit five-second
        // physical-display contract as bootstrap frontiers.
        assert_eq!(cadence.due(15_999), None);
        assert_eq!(
            cadence.due(16_000),
            Some((Cyw43NetworkReadyHdmiState::WaitingForTcpListener, true,))
        );
        cadence.clear(16_000);
        assert_eq!(cadence.due(u64::MAX), None);
    }

