    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_hdmi_progress_is_gate_aware_coalesced_and_cleared_by_terminal_status() {
        struct LinkedRuntimeTestReset;

        impl Drop for LinkedRuntimeTestReset {
            fn drop(&mut self) {
                crate::serial::test_end_linked_runtime_only_transport();
            }
        }

        let _progress_guard = wifi_driver_task_progress_test_guard();
        crate::serial::test_begin_linked_runtime_only_transport();
        let _reset = LinkedRuntimeTestReset;
        let driver = LoopbackSerial::<32768>::new();
        let serial = SerialPort::<_, 32768, 32768, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::repeated(8, 1);
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "pass").unwrap();
        let mut audit = AuditLog::new();
        let mut local_seat = LocalSeatRuntime::new(crate::local_seat::LocalSeatStatus {
            keyboard_device: "usb-kbd0",
            display_device: "hdmi0",
            line_bytes: 128,
            buffer_lines: 16,
        });
        local_seat.mark_root_console_ready();

        {
            let mut pump = EventPump::new(serial, timer, ipc, store, &mut audit)
                .with_local_seat(&mut local_seat);
            assert!(pump.queue_cyw43_bootstrap_supervisor_status(
                "CYW43_BOOTSTRAP_SUPERVISOR attempt=1 status=begin",
                "[drivers] WiFi bootstrap starting (single production attempt)",
            ));
            assert!(pump.queue_cyw43_bootstrap_operator_line(
                "CYW43_BOOTSTRAP_TURN attempt=1 turn=1 stage=cyw43-firmware-chunk operation=true repeat=1"
            ));

            // The start milestone is displayed first. Progress cannot appear
            // until five virtual seconds have elapsed.
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            pump.now_ms = CYW43_BOOTSTRAP_HDMI_PROGRESS_MIN_INTERVAL_MS - 1;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .pending_cyw43_bootstrap_hdmi_progress_milestone
                .is_none());

            pump.now_ms = CYW43_BOOTSTRAP_HDMI_PROGRESS_MIN_INTERVAL_MS;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| line == "[drivers] WiFi gate 6/10: uploading WiFi firmware"));

            // A changed internal stage in the same material frontier does not
            // create another line before the five-second heartbeat.
            assert!(pump.queue_cyw43_bootstrap_operator_line(
                "CYW43_BOOTSTRAP_TURN attempt=1 turn=2 stage=cyw43-nvram-chunk operation=true repeat=1"
            ));
            pump.now_ms = CYW43_BOOTSTRAP_HDMI_PROGRESS_MIN_INTERVAL_MS
                + CYW43_BOOTSTRAP_HDMI_PROGRESS_HEARTBEAT_MS
                - 1;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .pending_cyw43_bootstrap_hdmi_progress_milestone
                .is_none());
            pump.now_ms = CYW43_BOOTSTRAP_HDMI_PROGRESS_MIN_INTERVAL_MS
                + CYW43_BOOTSTRAP_HDMI_PROGRESS_HEARTBEAT_MS;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi gate 6/10: uploading WiFi firmware (still working)"
                }));

            assert!(pump.queue_cyw43_bootstrap_operator_line(
                "CYW43_BOOTSTRAP_TURN attempt=1 turn=3 stage=cyw43-control-security-wpa2-psk operation=true repeat=1"
            ));
            assert!(pump.queue_cyw43_bootstrap_supervisor_status_with_terminal(
                "CYW43_BOOTSTRAP_SUPERVISOR attempt=1 status=ready",
                "[drivers] WiFi driver ready; association and DHCP continuing",
                true,
            ));
            assert_eq!(pump.cyw43_bootstrap_hdmi_progress.attempt, 0);
            assert_eq!(pump.cyw43_bootstrap_hdmi_progress.current, None);
            assert_eq!(pump.cyw43_bootstrap_hdmi_progress.emitted, None);
            assert!(pump
                .pending_cyw43_bootstrap_hdmi_progress_milestone
                .is_none());
        }
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_hdmi_progress_cannot_be_starved_by_routine_serial_backlog() {
        struct LinkedRuntimeTestReset;

        impl Drop for LinkedRuntimeTestReset {
            fn drop(&mut self) {
                crate::serial::test_end_linked_runtime_only_transport();
            }
        }

        let _progress_guard = wifi_driver_task_progress_test_guard();
        crate::serial::test_begin_linked_runtime_only_transport();
        let _reset = LinkedRuntimeTestReset;
        let driver = LoopbackSerial::<32768>::new();
        let serial = SerialPort::<_, 32768, 32768, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::repeated(32, 1);
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "pass").unwrap();
        let mut audit = AuditLog::new();
        let mut local_seat = LocalSeatRuntime::new(crate::local_seat::LocalSeatStatus {
            keyboard_device: "usb-kbd0",
            display_device: "hdmi0",
            line_bytes: DEFAULT_LINE_CAPACITY as u16,
            buffer_lines: 32,
        });
        local_seat.mark_root_console_ready();

        {
            let mut pump = EventPump::new(serial, timer, ipc, store, &mut audit)
                .with_local_seat(&mut local_seat);
            assert!(pump.queue_cyw43_bootstrap_supervisor_status(
                "CYW43_BOOTSTRAP_SUPERVISOR attempt=1 status=begin",
                "[drivers] WiFi bootstrap starting (single production attempt)",
            ));
            for turn in 1..=(CONSOLE_OUTPUT_BACKLOG_LINES + 8) {
                let status = format!(
                    "CYW43_BOOTSTRAP_TURN attempt=1 turn={turn} stage=cyw43-cold-physical-lifetime-begin operation=true repeat={turn}"
                );
                let _ = pump.queue_cyw43_bootstrap_operator_line(status.as_str());
            }

            for _ in 0..4 {
                pump.poll_cyw43_bootstrap_supervisor_event_turn();
            }
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi bootstrap starting (single production attempt)"
                }));

            pump.now_ms = 4_999;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .pending_cyw43_bootstrap_hdmi_progress_milestone
                .is_none());

            // A bounded authenticated response tail may temporarily own the
            // physical operator turn. The due progress record must remain in
            // the one coalescing slot and become visible on the first eligible
            // display turn after the barrier clears.
            pump.now_ms = 5_000;
            pump.physical_response_barrier = PhysicalResponseBarrier::AwaitingTail;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .pending_cyw43_bootstrap_hdmi_progress_milestone
                .is_some());
            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi starting one CYW43/SDIO physical lifetime"
                }));
            pump.physical_response_barrier = PhysicalResponseBarrier::Idle;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi starting one CYW43/SDIO physical lifetime"
                }));

            pump.now_ms = 9_999;
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi starting one CYW43/SDIO physical lifetime (still working)"
                }));
            pump.now_ms = 10_000;
            for _ in 0..4 {
                pump.poll_cyw43_bootstrap_supervisor_event_turn();
            }
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line == "[drivers] WiFi starting one CYW43/SDIO physical lifetime (still working)"
                }));
        }
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn deferred_wifi_hdmi_ready_releases_only_after_terminal_milestone() {
        let driver = LoopbackSerial::<8192>::new();
        let serial = SerialPort::<_, 8192, 8192, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::repeated(8, 1);
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "pass").unwrap();
        let mut audit = AuditLog::new();
        let mut local_seat = LocalSeatRuntime::new(crate::local_seat::LocalSeatStatus {
            keyboard_device: "usb-kbd0",
            display_device: "hdmi0",
            line_bytes: 96,
            buffer_lines: 16,
        });

        {
            let mut pump = EventPump::new(serial, timer, ipc, store, &mut audit)
                .with_local_seat(&mut local_seat);
            pump.defer_local_seat_hdmi_ready_until_cyw43_terminal();
            pump.announce_console_ready();

            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .hdmi_bootstrap_terminal_ready());
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| {
                    line.as_str() == "Cohesix startup in progress; serial console available"
                }));
            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| line.as_str() == "Cohesix serial console ready"));

            assert!(pump.queue_cyw43_bootstrap_supervisor_status_with_terminal(
                "CYW43_BOOTSTRAP_SUPERVISOR attempt=1 status=begin",
                "[drivers] WiFi bootstrap starting (single production attempt)",
                false,
            ));
            assert!(pump.queue_cyw43_bootstrap_supervisor_status_with_terminal(
                "CYW43_BOOTSTRAP_SUPERVISOR attempt=1 status=failed",
                "[drivers] WiFi startup failed; diagnostics remain active",
                true,
            ));

            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .hdmi_bootstrap_terminal_ready());
            pump.local_seat
                .as_mut()
                .unwrap()
                .release_linked_hdmi_console_for_test(CONSOLE_PROMPT);
            assert!(!pump
                .local_seat
                .as_ref()
                .unwrap()
                .mirrored_lines_snapshot()
                .iter()
                .any(|line| line.as_str() == "Cohesix console ready"));
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            pump.poll_cyw43_bootstrap_supervisor_event_turn();
            assert!(pump
                .local_seat
                .as_ref()
                .unwrap()
                .hdmi_bootstrap_terminal_ready());
            let runtime = pump.local_seat.as_mut().unwrap();
            runtime.release_linked_hdmi_console_for_test(CONSOLE_PROMPT);
            runtime.release_linked_hdmi_console_for_test(CONSOLE_PROMPT);
        }

        let lines = local_seat.mirrored_lines_snapshot();
        let begin = lines
            .iter()
            .position(|line| {
                line == "[drivers] WiFi bootstrap starting (single production attempt)"
            })
            .expect("begin milestone reaches HDMI first");
        let terminal = lines
            .iter()
            .position(|line| line == "[drivers] WiFi startup failed; diagnostics remain active")
            .expect("terminal milestone reaches HDMI");
        let ready = lines
            .iter()
            .position(|line| line == "Cohesix console ready")
            .expect("one final ready banner follows the terminal milestone");
        let prompt = lines
            .iter()
            .position(|line| line == CONSOLE_PROMPT)
            .expect("interactive prompt follows the ready banner");
        assert!(begin < terminal);
        assert!(terminal < ready);
        assert!(ready < prompt);
        assert_eq!(
            lines
                .iter()
                .filter(|line| line.as_str() == "Cohesix console ready")
                .count(),
            1
        );
        assert_eq!(
            lines
                .iter()
                .filter(|line| line.as_str() == CONSOLE_PROMPT)
                .count(),
            1
        );
    }

    #[test]
    fn console_ready_announcement_is_idempotent() {
        let driver = LoopbackSerial::<8192>::new();
        let serial = SerialPort::<_, 8192, 8192, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::single(TickEvent {
            tick: 1,
            now_ms: 10,
        });
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "pass").unwrap();
        let mut audit = AuditLog::new();
        let mut local_seat = LocalSeatRuntime::new(crate::local_seat::LocalSeatStatus {
            keyboard_device: "usb-kbd0",
            display_device: "hdmi0",
            line_bytes: 32,
            buffer_lines: 4,
        });
        let mut pump =
            EventPump::new(serial, timer, ipc, store, &mut audit).with_local_seat(&mut local_seat);

        pump.announce_console_ready();
        let first_ready = pump.serial_mut().driver_mut().drain_tx();
        let first_transcript = core::str::from_utf8(first_ready.as_slice()).unwrap();
        assert_eq!(first_transcript.matches("Cohesix console ready").count(), 1);
        assert_eq!(first_transcript.matches("Commands:").count(), 1);
        #[cfg(all(feature = "kernel", feature = "usb"))]
        assert!(pump.post_prompt_local_seat_attach_pending_for_test());

        #[cfg(all(feature = "kernel", feature = "usb"))]
        {
            pump.post_prompt_local_seat_attach_pending = false;
        }
        pump.announce_console_ready();
        let second_ready = pump.serial_mut().driver_mut().drain_tx();
        let second_transcript = core::str::from_utf8(second_ready.as_slice()).unwrap();
        assert!(!second_transcript.contains("Cohesix console ready"));
        assert!(!second_transcript.contains("Commands:"));
        assert!(!second_transcript.contains(CONSOLE_PROMPT));
        #[cfg(all(feature = "kernel", feature = "usb"))]
        assert!(!pump.post_prompt_local_seat_attach_pending_for_test());
    }

