    #[test]
    fn local_seat_usb_burst_proof_requires_caught_up_zero_drop_echo() {
        let burst_bytes =
            (LOCAL_SEAT_BURST_DRAIN_PASSES_PER_TURN * KEYBOARD_POLL_CHUNK_BYTES) as u64;

        assert!(local_seat_usb_burst_proof(
            burst_bytes,
            burst_bytes,
            burst_bytes,
            0
        ));
        assert!(!local_seat_usb_burst_proof(
            burst_bytes - 1,
            burst_bytes - 1,
            burst_bytes - 1,
            0
        ));
        assert!(!local_seat_usb_burst_proof(
            burst_bytes,
            burst_bytes - 1,
            burst_bytes,
            0
        ));
        assert!(!local_seat_usb_burst_proof(
            burst_bytes,
            burst_bytes,
            burst_bytes - 1,
            0
        ));
        assert!(!local_seat_usb_burst_proof(
            burst_bytes,
            burst_bytes,
            burst_bytes,
            1
        ));
    }

    struct NullIpc;

    impl IpcDispatcher for NullIpc {
        fn dispatch(&mut self, _now_ms: u64) {}
    }

    #[test]
    fn usb_runtime_progress_supersession_requires_command_ready() {
        type ConsoleTestPump =
            EventPump<'static, LoopbackSerial<32>, TestTimer, NullIpc, TicketTable<4>, 32, 32, 32>;

        assert!(ConsoleTestPump::usb_runtime_progress_superseded_by_command_ready(true, 10, 7));
        assert!(!ConsoleTestPump::usb_runtime_progress_superseded_by_command_ready(false, 10, 7));
        assert!(!ConsoleTestPump::usb_runtime_progress_superseded_by_command_ready(true, 10, 10));
    }

    #[cfg(feature = "kernel")]
    type KernelConsoleTestPump =
        EventPump<'static, LoopbackSerial<32>, TestTimer, NullIpc, TicketTable<4>, 32, 32, 32>;

    #[cfg(feature = "kernel")]
