    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_sdio_dpc_diagnostic_lines_preserve_truth_without_truncation() {
        let diagnostic = crate::drivers::driver_task_net::Cyw43SdioDpcDiagnostic {
            generation: u32::MAX,
            event_attempts: u32::MAX,
            published: u32::MAX,
            consumed: u32::MAX,
            sample_consumer: u32::MAX,
            rearms: u32::MAX,
            overruns: u32::MAX,
            epoch_errors: u32::MAX,
            sequence_errors: u32::MAX,
            ack_failures: u32::MAX,
            ring_poisoned: false,
            client_sample_stale: true,
            poisoned: true,
            masked: true,
        };
        let cause_diagnostic = crate::drivers::driver_task_net::Cyw43SdioDpcCauseDiagnostic {
            generation: u32::MAX,
            samples: u32::MAX,
            frame: u32::MAX,
            hostmail: u32::MAX,
            fc_change: u32::MAX,
            fc_state: u32::MAX,
            chipactive: u32::MAX,
            other: u32::MAX,
            spurious: u32::MAX,
            frames: u32::MAX,
            dpc_turns: u32::MAX,
            children: u32::MAX,
            owner_turns: u32::MAX,
            frame_dpc_turns: u32::MAX,
            frame_owner_turns: u32::MAX,
        };
        let accounting = KernelConsoleTestPump::wifi_sdio_dpc_accounting_line(diagnostic);
        let scope = KernelConsoleTestPump::wifi_sdio_dpc_scope_line();
        let truth = KernelConsoleTestPump::wifi_sdio_dpc_truth_line(diagnostic);
        let rearm = KernelConsoleTestPump::wifi_sdio_dpc_rearm_line(diagnostic);
        let cause = KernelConsoleTestPump::wifi_sdio_dpc_cause_line(cause_diagnostic);

        for line in [&accounting, &scope, &truth, &rearm, &cause] {
            assert!(
                !line.contains(DIAGNOSTIC_TRUNCATION_MARKER),
                "DPC telemetry must remain parseable: {line}"
            );
            assert!(line.len() < DEFAULT_LINE_CAPACITY, "{line}");
        }
        assert!(accounting.ends_with("poisoned=yes masked=yes"));
        assert_eq!(
            scope.as_str(),
            "CYW43_SDIO_DPC_SCOPE captures=event-attempts published=ring-events source=card-int-or-source-probe physical_card_irq=not-exported"
        );
        assert!(truth.contains("ring_poisoned=no client_sample_stale=yes"));
        assert!(truth.contains("ring_consumer=4294967295 sample_consumer=4294967295"));
        assert!(truth.ends_with(
            "sample_reason=ring-consumer-mismatch authority=live-ring action=rerun-proof"
        ));
        assert!(rearm.contains("counter=client-signal-attempts count=4294967295 owner_irq=masked"));
        assert!(rearm.ends_with("action=service-sdio-owner"));
        assert!(cause
            .starts_with("CYW43_SDIO_DPC_CAUSE samples=4294967295 frm=4294967295 hm=4294967295"));
        assert!(cause.contains(
            "fcc=4294967295 fcs=4294967295 ca=4294967295 other=4294967295 spur=4294967295 done=4294967295"
        ));
        assert!(cause.ends_with(
            "dpc=4294967295 child=4294967295 owner=4294967295 fdpc=4294967295 fown=4294967295"
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_retained_gate8_terminal_requires_logical_fault_authority() {
        let mut terminal = crate::drivers::driver_task_net::Cyw43TerminalDrainDiagnostic {
            generation: 2,
            stage: "cyw43-host-eapol-data-poll",
            request: 3_780,
            descriptor_op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            descriptor_arg0: 0,
            descriptor_arg1: 0,
            completion_code: 5,
            completion_detail: 1,
            completion_result: 0,
            completion_frame_offset: 0,
            completion_frame_len: 0,
            completion_frame_flags: 0,
            logical_terminal: true,
            logical_owner_conflict: false,
            logical_owner_generation: 0,
            logical_owner_stage: "none",
            logical_owner_cmd: 0,
            logical_owner_id: 0,
            logical_owner_payload_fingerprint: 0,
        };
        assert!(KernelConsoleTestPump::wifi_terminal_drain_is_gate8_fault(
            terminal,
        ));

        terminal.logical_terminal = false;
        terminal.logical_owner_conflict = true;
        assert!(
            !KernelConsoleTestPump::wifi_terminal_drain_is_gate8_fault(terminal),
            "a competing physical owner receipt cannot replace the primitive logical cause",
        );
        assert!(
            KernelConsoleTestPump::wifi_terminal_drain_is_gate8_physical_carrier(terminal),
            "the exact physical completion remains first-cause evidence",
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_gate8_physical_carrier_reason(terminal),
            "linked-runtime-terminal-untyped",
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_gate8_physical_carrier_reason(
                crate::drivers::driver_task_net::Cyw43TerminalDrainDiagnostic {
                    completion_result:
                        pi4_driver_abi::DRIVER_RUNTIME_REJECT_SDIO_REQUEST_IDENTITY_INVALID,
                    ..terminal
                },
            ),
            "sdio-request-identity-invalid",
        );
        let matching_fault = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            stage: terminal.stage,
            op: terminal.descriptor_op,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            control_cmd: terminal.descriptor_arg0,
            control_id: terminal.descriptor_arg1 as u16,
            control_header_mode: "plain",
            control_response_len: 0,
            detail: terminal.completion_detail,
            reason: "rejected-command",
            result: terminal.completion_result,
        };
        assert!(
            KernelConsoleTestPump::wifi_runtime_fault_matches_terminal_drain(
                matching_fault,
                terminal,
            ),
            "the retained terminal suppresses its duplicate latest status",
        );
        assert!(
            !KernelConsoleTestPump::wifi_runtime_fault_matches_terminal_drain(
                crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
                    stage: "cyw43-host-eapol-data-poll-recovery",
                    ..matching_fault
                },
                terminal,
            ),
            "a distinct terminal stage remains visible as recovery residue",
        );
        let carrier =
            KernelConsoleTestPump::wifi_diag_first_causal_physical_completion_line(terminal);
        assert!(carrier.contains("role=carrier logical_terminal_proven=no"));
        assert!(carrier.contains("request=3780 completion_sequence=3780"));
        assert!(carrier.contains("exact_request_match=yes current_state=secondary"));
        assert!(!carrier.contains(DIAGNOSTIC_TRUNCATION_MARKER));
    }

    #[cfg(feature = "kernel")]
    struct StubIpc {
        dispatched: bool,
        message: Option<BootstrapMessage>,
    }

    #[cfg(feature = "kernel")]
    impl StubIpc {
        fn new(message: BootstrapMessage) -> Self {
            Self {
                dispatched: false,
                message: Some(message),
            }
        }
    }

    #[cfg(feature = "kernel")]
    impl IpcDispatcher for StubIpc {
        fn dispatch(&mut self, _now_ms: u64) {
            self.dispatched = true;
        }

        fn take_bootstrap_message(&mut self) -> Option<BootstrapMessage> {
            if self.dispatched {
                self.message.take()
            } else {
                None
            }
        }
    }

    #[cfg(feature = "kernel")]
    struct ProbeIpc {
        staged: Option<BootstrapMessage>,
        pending: Option<BootstrapMessage>,
        polls: u32,
    }

    #[cfg(feature = "kernel")]
    impl ProbeIpc {
        fn new(message: BootstrapMessage) -> Self {
            Self {
                staged: None,
                pending: Some(message),
                polls: 0,
            }
        }
    }

    #[cfg(feature = "kernel")]
    impl IpcDispatcher for ProbeIpc {
        fn dispatch(&mut self, _now_ms: u64) {
            if self.staged.is_none() {
                self.staged = self.pending.take();
            }
        }

        fn take_bootstrap_message(&mut self) -> Option<BootstrapMessage> {
            self.staged.take()
        }

        fn bootstrap_poll(&mut self, _now_ms: u64) -> bool {
            self.polls = self.polls.saturating_add(1);
            if self.polls > 1 {
                panic!("bootstrap probe failed to observe drained message");
            }
            false
        }
    }

    struct AuditLog {
        entries: heapless::Vec<HeaplessString<64>, 32>,
        denials: heapless::Vec<HeaplessString<64>, 32>,
    }

    impl AuditLog {
        fn new() -> Self {
            Self {
                entries: heapless::Vec::new(),
                denials: heapless::Vec::new(),
            }
        }
    }

    fn issue_token(secret: &str, role: Role) -> String {
        let budget = match role {
            Role::Queen => BudgetSpec::unbounded(),
            Role::WorkerHeartbeat => BudgetSpec::default_heartbeat(),
            Role::WorkerGpu => BudgetSpec::default_gpu(),
            Role::WorkerBus => BudgetSpec::default_heartbeat(),
            Role::WorkerLora => BudgetSpec::default_heartbeat(),
        };
        let issuer = TicketIssuer::new(secret);
        let claims = TicketClaims::new(role, budget, None, MountSpec::empty(), unix_time_ms());
        issuer.issue(claims).unwrap().encode().unwrap()
    }

    fn command_path(value: &str) -> heapless::String<{ cohsh_core::MAX_PATH_LEN }> {
        let mut path = heapless::String::new();
        path.push_str(value)
            .expect("test command path must fit MAX_PATH_LEN");
        path
    }

    fn unix_time_ms() -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64
    }

    impl AuditSink for AuditLog {
        fn info(&mut self, message: &str) {
            let mut buf = HeaplessString::new();
            let _ = buf.push_str(message);
            let _ = self.entries.push(buf);
        }

        fn denied(&mut self, message: &str) {
            let mut buf = HeaplessString::new();
            let _ = buf.push_str(message);
            let _ = self.denials.push(buf);
        }
    }

    #[cfg(feature = "kernel")]
    struct ReachableRootGuard;

    #[cfg(feature = "kernel")]
    impl ReachableRootGuard {
        fn new(now_ms: u64) -> Self {
            crate::lifecycle::root_mark_session_active(now_ms);
            Self
        }
    }

    #[cfg(feature = "kernel")]
    impl Drop for ReachableRootGuard {
        fn drop(&mut self) {
            crate::lifecycle::root_mark_cut(crate::lifecycle::RootCutReason::NetworkUnreachable);
        }
    }

    #[cfg(feature = "net-console")]
    struct FakeNet {
        lines: heapless::Vec<ConsoleLine, 128>,
        sent: heapless::Vec<HeaplessString<DEFAULT_LINE_CAPACITY>, 128>,
        start_result: NetSelfTestStartResult,
        self_test_starts: usize,
        status: NetStatusReport,
        status_reports: core::cell::Cell<usize>,
        counters: NetCounters,
        self_test_report: NetSelfTestReport,
        polls: usize,
        tcp_flushes: usize,
        tcp_flush_send_counts: heapless::Vec<usize, 32>,
        tcp_flush_activity_remaining: usize,
        release_line_after_flush_poll: bool,
        released_line_after_flush_poll: bool,
        idle_flush_polls_before_release: usize,
        tcp_ready_after_polls: Option<usize>,
        listener_ready: bool,
        exhaust_poll_budget: bool,
        exhaust_flush_budget: bool,
        disconnect_requests: usize,
        active_conn_id: Option<u64>,
        authenticated_conn_id: Option<u64>,
        console_service_pending: bool,
        icmp_echo_due: bool,
        console_output_drained: bool,
        console_output_drained_after_polls: Option<usize>,
        events: heapless::Vec<NetConsoleEvent, 8>,
        driver_contract: crate::hal::driver_task::DriverTaskContract,
    }

    #[cfg(feature = "net-console")]
    impl FakeNet {
        fn new() -> Self {
            Self {
                lines: heapless::Vec::new(),
                sent: heapless::Vec::new(),
                start_result: NetSelfTestStartResult::Unsupported,
                self_test_starts: 0,
                status: NetStatusReport::default(),
                status_reports: core::cell::Cell::new(0),
                counters: NetCounters::default(),
                self_test_report: NetSelfTestReport::default(),
                polls: 0,
                tcp_flushes: 0,
                tcp_flush_send_counts: heapless::Vec::new(),
                tcp_flush_activity_remaining: 0,
                release_line_after_flush_poll: false,
                released_line_after_flush_poll: false,
                idle_flush_polls_before_release: 0,
                tcp_ready_after_polls: None,
                listener_ready: false,
                exhaust_poll_budget: false,
                exhaust_flush_budget: false,
                disconnect_requests: 0,
                active_conn_id: None,
                authenticated_conn_id: None,
                console_service_pending: false,
                icmp_echo_due: false,
                console_output_drained: true,
                console_output_drained_after_polls: None,
                events: heapless::Vec::new(),
                driver_contract: crate::hal::driver_task::VIRTIO_NET_DRIVER_TASK_CONTRACT,
            }
        }
    }

    #[cfg(feature = "net-console")]
    impl NetPoller for FakeNet {
        fn poll(&mut self, _now_ms: u64) -> bool {
            self.polls = self.polls.saturating_add(1);
            if self
                .tcp_ready_after_polls
                .is_some_and(|target| self.polls >= target)
            {
                self.status.tcp_ready = true;
            }
            if self.release_line_after_flush_poll
                && !self.released_line_after_flush_poll
                && self.tcp_flushes != 0
            {
                if self.idle_flush_polls_before_release != 0 {
                    self.idle_flush_polls_before_release =
                        self.idle_flush_polls_before_release.saturating_sub(1);
                    return false;
                }
                let mut line = HeaplessString::new();
                assert!(line.push_str("ping").is_ok());
                assert!(self.lines.push(ConsoleLine::new(line, 9001)).is_ok());
                self.released_line_after_flush_poll = true;
            }
            true
        }

        fn poll_with_budget(
            &mut self,
            _now_ms: u64,
            budget: &mut DriverServiceBudget,
        ) -> Result<bool, crate::hal::driver_task::DriverServiceBudgetError> {
            if self.exhaust_poll_budget {
                budget.charge_bytes(self.driver_task_contract().budget.max_bytes_per_turn)?;
            } else {
                budget.charge_ops(1)?;
                budget.charge_frames(1)?;
            }
            Ok(self.poll(_now_ms))
        }

        fn flush_tcp_with_budget(
            &mut self,
            _now_ms: u64,
            budget: &mut DriverServiceBudget,
        ) -> Result<bool, crate::hal::driver_task::DriverServiceBudgetError> {
            if self.exhaust_flush_budget {
                budget.charge_bytes(self.driver_task_contract().budget.max_bytes_per_turn)?;
            }
            self.tcp_flushes = self.tcp_flushes.saturating_add(1);
            let _ = self.tcp_flush_send_counts.push(self.sent.len());
            let activity = self.tcp_flush_activity_remaining != 0;
            self.tcp_flush_activity_remaining = self.tcp_flush_activity_remaining.saturating_sub(1);
            Ok(activity)
        }

        fn driver_task_contract(&self) -> crate::hal::driver_task::DriverTaskContract {
            self.driver_contract
        }

        fn telemetry(&self) -> NetTelemetry {
            NetTelemetry {
                link_up: true,
                tx_drops: 0,
                last_poll_ms: 0,
            }
        }

        fn stats(&self) -> NetCounters {
            self.counters
        }

        fn drain_console_lines(&mut self, _now_ms: u64, visitor: &mut dyn FnMut(ConsoleLine)) {
            let _ = self.drain_console_lines_bounded(_now_ms, usize::MAX, visitor);
        }

        fn drain_console_lines_bounded(
            &mut self,
            _now_ms: u64,
            max_lines: usize,
            visitor: &mut dyn FnMut(ConsoleLine),
        ) -> usize {
            let mut drained = 0usize;
            while !self.lines.is_empty() {
                if drained >= max_lines {
                    break;
                }
                let line = self.lines.remove(0);
                visitor(line);
                drained = drained.saturating_add(1);
            }
            drained
        }

        fn ingest_snapshot(&self) -> IngestSnapshot {
            IngestSnapshot {
                queued: u32::try_from(self.lines.len()).unwrap_or(u32::MAX),
                ..IngestSnapshot::default()
            }
        }

        fn send_console_line(&mut self, line: &str) -> bool {
            let mut buf = HeaplessString::new();
            if buf.push_str(line).is_err() {
                return false;
            }
            let _ = self.sent.push(buf);
            true
        }

        fn request_disconnect(&mut self) {
            self.disconnect_requests = self.disconnect_requests.saturating_add(1);
        }

        fn console_output_drained(&self, conn_id: u64) -> bool {
            self.active_conn_id == Some(conn_id)
                && (self.console_output_drained
                    || self
                        .console_output_drained_after_polls
                        .is_some_and(|target| self.polls >= target))
        }

        fn drain_console_events(&mut self, visitor: &mut dyn FnMut(NetConsoleEvent)) {
            while !self.events.is_empty() {
                visitor(self.events.remove(0));
            }
        }

        fn active_console_conn_id(&self) -> Option<u64> {
            self.active_conn_id
        }

        fn authenticated_console_conn_id(&self) -> Option<u64> {
            self.authenticated_conn_id
        }

        fn console_service_pending(&self) -> bool {
            self.console_service_pending
        }

        fn icmp_echo_service_due(&self, _now_ms: u64) -> bool {
            self.icmp_echo_due
        }

        fn console_listener_ready(&self) -> bool {
            self.listener_ready
        }

        fn start_self_test(&mut self, _now_ms: u64) -> NetSelfTestStartResult {
            self.self_test_starts = self.self_test_starts.saturating_add(1);
            self.start_result
        }

        fn self_test_report(&self) -> NetSelfTestReport {
            self.self_test_report.clone()
        }

        fn status_report(&self) -> NetStatusReport {
            self.status_reports
                .set(self.status_reports.get().saturating_add(1));
            self.status.clone()
        }
    }

