        net.counters.tx_packets = 777;
        net.counters.tcp_rx_bytes = 65_535;
        net.counters.wifi_host_eapol_secure = 1;
        let mut pump = EventPump::new(serial, timer, ipc, store, &mut audit).with_network(&mut net);
