    #[cfg(feature = "net-console")]
    #[test]
    fn linked_runtime_dhcp_lease_data_paths_need_physical_pressure_service() {
        let mut wired = NetStatusReport::default();
        wired.profile_backend = "bcmgenet-v5";
        wired.backend = "bcmgenet-v5";
        wired.active_driver = "bcmgenet-v5";
        wired.active_interface = "wired";
        wired.address_source = "dhcp-lease";
        wired.dhcp_phase = "bound";
        assert!(net_status_needs_physical_pressure_service(&wired));

        let mut wifi = wired.clone();
        wifi.active_driver = "cyw43";
        wifi.active_interface = "wifi";
        assert!(net_status_needs_physical_pressure_service(&wifi));

        let mut stack_reported_wifi = wired.clone();
        stack_reported_wifi.active_driver = "cyw43";
        stack_reported_wifi.active_interface = "wifi";
        assert!(net_status_needs_physical_pressure_service(
            &stack_reported_wifi
        ));

        let mut pre_lease = wired.clone();
        pre_lease.address_source = "dhcp-pending";
        pre_lease.dhcp_phase = "requesting";
        assert!(!net_status_needs_physical_pressure_service(&pre_lease));

        let mut wifi_dhcp_pending = pre_lease.clone();
        wifi_dhcp_pending.active_driver = "cyw43";
        wifi_dhcp_pending.active_interface = "wifi";
        assert!(net_status_needs_physical_pressure_service(
            &wifi_dhcp_pending
        ));

        let mut wifi_host_eapol = wifi.clone();
        wifi_host_eapol.address_source = "wifi-host-eapol-required";
        wifi_host_eapol.dhcp_phase = "host-eapol-required";
        assert!(!net_status_needs_physical_pressure_service(
            &wifi_host_eapol
        ));
    }

    #[cfg(feature = "net-console")]
    #[test]
    fn post_dispatch_flush_limit_extends_under_display_pressure() {
        let mut genet = NetStatusReport::default();
        genet.profile_backend = "bcmgenet-v5";
        genet.backend = "bcmgenet-v5";
        genet.active_driver = "bcmgenet-v5";
        genet.active_interface = "wired";
        genet.address_source = "dhcp-lease";
        genet.dhcp_phase = "bound";
        let mut wifi = genet.clone();
        wifi.active_driver = "cyw43";
        wifi.active_interface = "wifi";
        let mut stack_reported_wifi = genet.clone();
        stack_reported_wifi.active_driver = "cyw43";
        stack_reported_wifi.active_interface = "wifi";

        assert_eq!(
            net_post_dispatch_flush_limit_for_display(None),
            NET_POST_DISPATCH_FLUSH_POLLS
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_display(Some(LocalSeatDisplayTrace::default())),
            NET_POST_DISPATCH_FLUSH_POLLS
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&genet, None),
            Some(NET_POST_DISPATCH_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&wifi, None),
            Some(NET_POST_DISPATCH_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&stack_reported_wifi, None),
            Some(NET_POST_DISPATCH_FLUSH_POLLS)
        );

        let mut pending = LocalSeatDisplayTrace {
            pending_bytes: 1,
            ..LocalSeatDisplayTrace::default()
        };
        assert_eq!(
            net_post_dispatch_flush_limit_for_display(Some(pending)),
            NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&genet, Some(pending)),
            Some(NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&wifi, Some(pending)),
            Some(NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&stack_reported_wifi, Some(pending)),
            Some(NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS)
        );

        pending = LocalSeatDisplayTrace {
            no_reply_frames: 1,
            deferred_frames: 2,
            submitted_frames: 1,
            ..LocalSeatDisplayTrace::default()
        };
        assert_eq!(
            net_post_dispatch_flush_limit_for_display(Some(pending)),
            NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&genet, Some(pending)),
            Some(NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&wifi, Some(pending)),
            Some(NET_POST_DISPATCH_BACKLOG_FLUSH_POLLS)
        );

        pending = LocalSeatDisplayTrace {
            no_reply_frames: 1,
            deferred_frames: 1,
            submitted_frames: 2,
            ..LocalSeatDisplayTrace::default()
        };
        assert_eq!(
            net_post_dispatch_flush_limit_for_display(Some(pending)),
            NET_POST_DISPATCH_FLUSH_POLLS
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&genet, Some(pending)),
            Some(NET_POST_DISPATCH_FLUSH_POLLS)
        );
        assert_eq!(
            net_post_dispatch_flush_limit_for_status(&wifi, Some(pending)),
            Some(NET_POST_DISPATCH_FLUSH_POLLS)
        );
    }

