    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_startup_gate_status_marks_unproven_prefault_gates_as_inferred() {
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(1, 1, 6),
            "pass"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(5, 1, 6),
            "inferred"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(6, 1, 6),
            "fail"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(7, 1, 6),
            "blocked"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_direct_proof_gate(7, Some(2), false),
            1,
            "a stale later proof must not pass the terminal card-select gate"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_reported_proof_gate(1, Some(2)),
            1
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_direct_proof_gate(7, Some(6), false),
            5,
            "a stale later proof must stop before the terminal firmware gate"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_reported_proof_gate(5, Some(6)),
            5
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_direct_proof_gate(1, Some(6), false),
            1
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_reported_proof_gate(1, Some(6)),
            5,
            "the inferred frontier may identify the cut without inventing direct proof"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(6, 5, 6),
            "fail"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_startup_gate_status(7, 5, 6),
            "blocked"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_gate_one_requires_one_completed_supervisor_bound_physical_lifetime() {
        let completed = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 9,
            completed_epoch: 9,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        let active = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 9,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        let failed = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 9,
            failed_epoch: 9,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        let invalid = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            magic: 0,
            ..completed
        };

        assert!(!KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            None, true,
        ));
        assert!(!KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            Some(active),
            true,
        ));
        assert!(!KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            Some(failed),
            true,
        ));
        assert!(!KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            Some(invalid),
            true,
        ));
        assert!(!KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            Some(completed),
            false,
        ));
        assert!(KernelConsoleTestPump::wifi_physical_lifetime_gate_ready(
            Some(completed),
            true,
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_nested_sdio_fault_uses_only_same_operation_progress_gate() {
        let transport_fault = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-transport-init",
            op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            control_cmd: 0,
            control_id: 0,
            control_header_mode: "not-control",
            control_response_len: 0,
            detail: 0x5103,
            reason: "sdio-descriptor-transfer-failed",
            result: 0x020c_8000,
        };
        let window_low = crate::hal::driver_task::DriverTaskRingProgressSnapshot {
            marker_valid: true,
            sequence: 3,
            phase: pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_BACKPLANE_WINDOW_LOW,
            phase_name: "cyw43-backplane-window-low",
            aux0: pi4_driver_abi::DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        };

        assert_eq!(
            KernelConsoleTestPump::wifi_contextual_nested_sdio_fault_gate(
                transport_fault,
                window_low,
            ),
            Some(5)
        );

        let unrelated_firmware_fault =
            crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
                stage: "cyw43-firmware-chunk",
                op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK,
                ..transport_fault
            };
        assert_eq!(
            KernelConsoleTestPump::wifi_contextual_nested_sdio_fault_gate(
                unrelated_firmware_fault,
                window_low,
            ),
            None,
            "stale transport progress must not relabel a firmware transfer fault"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_runtime_fault_gate(unrelated_firmware_fault),
            6
        );

        let explicit_backplane_fault =
            crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
                detail: 0x5321,
                reason: "cyw43-backplane-window",
                ..transport_fault
            };
        assert_eq!(
            KernelConsoleTestPump::wifi_contextual_nested_sdio_fault_gate(
                explicit_backplane_fault,
                window_low,
            ),
            None,
            "an explicit fault detail must retain its own gate mapping"
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_runtime_fault_gate(explicit_backplane_fault),
            5
        );
    }

