    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_root_grant_rejection_precedes_secondary_host_eapol_recovery() {
        let _progress_guard = wifi_driver_task_progress_test_guard();
        let cyw43 = crate::hal::driver_task::CYW43_WIFI_DRIVER_TASK_CONTRACT;
        crate::hal::driver_task::test_record_driver_task_ring_progress_snapshot(
            cyw43,
            1_345,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_REJECTED,
            pi4_driver_abi::DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        );
        crate::drivers::driver_task_net::test_record_cyw43_deferred_recovery_diagnostic(
            crate::drivers::driver_task_net::Cyw43DeferredRecoveryDiagnostic {
                cause: "issued-owner-unknown",
                subphase: "cyw43-host-eapol-control-poll",
                generation: 0,
                owner_generation: 0,
                descriptor_op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
                descriptor_flags: 0x0003,
                descriptor_target_addr: 0,
                descriptor_payload_offset: 0,
                descriptor_payload_len: 0,
                descriptor_total_len: 0,
                descriptor_arg0: 0,
                descriptor_arg1: 0,
                ticket_id: 0x1122_3344_5566_7788,
                completion_detail: 0x5310,
                completion_result: 0x4359_0008,
                completion_sequence: 1_345,
                terminal_observed: true,
                turn_id: 701,
                gate: 8,
            },
        );
        crate::drivers::driver_task_net::test_record_cyw43_terminal_drain_diagnostic(
            crate::drivers::driver_task_net::Cyw43TerminalDrainDiagnostic {
                generation: 0,
                stage: "cyw43-host-eapol-data-poll",
                request: 3_780,
                descriptor_op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_RX_POLL,
                descriptor_arg0: 0,
                descriptor_arg1: 0,
                completion_code: 5,
                completion_detail: 1,
                completion_result: 0,
                completion_frame_offset: 0,
                completion_frame_len: 0,
                completion_frame_flags: 0,
                logical_terminal: true,
                logical_owner_conflict: false,
                logical_owner_generation: 0,
                logical_owner_stage: "none",
                logical_owner_cmd: 0,
                logical_owner_id: 0,
                logical_owner_payload_fingerprint: 0,
            },
        );

        let driver = LoopbackSerial::<32768>::new();
        let serial = SerialPort::<_, 32768, 32768, DEFAULT_LINE_CAPACITY>::new(driver);
        let timer = TestTimer::single(TickEvent { tick: 1, now_ms: 1 });
        let ipc = NullIpc;
        let mut store: TicketTable<4> = TicketTable::new();
        store.register(Role::Queen, "ticket").unwrap();
        let mut audit = AuditLog::new();
        let mut pump =
            EventPump::new(serial, timer, ipc, store, &mut audit).with_test_pi4_debug_commands();

        pump.serial_mut().driver_mut().push_rx(b"wifi diag\n");
        let mut transcript = Vec::new();
        for _ in 0..256 {
            pump.poll();
            transcript.extend(pump.serial_mut().driver_mut().drain_tx());
        }
        transcript.extend(pump.serial_mut().driver_mut().drain_tx());
        drop(pump);
        let rendered = String::from_utf8(transcript).expect("serial output must be utf8");

        assert!(
            rendered.contains(
                "wifi: deferred_recovery retained=yes refinement=exact-owner logical_terminal_observed=yes cause=issued-owner-unknown subphase=cyw43-host-eapol-control-poll gate=8"
            ),
            "{rendered}"
        );
        assert!(
            rendered.contains(
                "wifi: deferred_recovery identity generation=0 owner_generation=0 ticket=1234605616436508552 completion_detail=0x5310 completion_result=0x43590008 completion_sequence=1345 turn=701"
            ),
            "{rendered}"
        );
        assert!(
            rendered.contains(
                "wifi: deferred_recovery descriptor op=0x000a flags=0x0003 target=0x00000000"
            ),
            "{rendered}"
        );
        assert!(
            rendered.contains(
                "wifi: evidence first_causal_terminal authority=retained-first gate=8 stage=cyw43-host-eapol-data-poll request=3780 carrier_op=0x0008 detail=0x0001 result=0x00000000 current_state=secondary"
            ),
            "{rendered}"
        );
        assert!(
            rendered.contains(
                "wifi: cyw43 last_progress marker_valid=yes sequence=1345 phase=467 phase_name=root-grant-rejected"
            ) && rendered.contains("gate=0 superseded=yes"),
            "{rendered}"
        );
        assert!(
            rendered.contains("wifi: gate 2 name=sdio-card-select status=blocked"),
            "{rendered}"
        );
        assert!(
            rendered.contains("wifi: gate 8 name=host-eapol status=blocked")
                && rendered
                    .contains("exact=cyw43-host-eapol-control-poll control_stage=host-eapol"),
            "{rendered}"
        );
        assert!(
            rendered.contains(
                "wifi: next_action=inspect-root-request-fingerprint-and-generation blocker=cyw43-root-grant-identity-rejected proof_gate=0 target_gate=10"
            ),
            "{rendered}"
        );
        assert!(
            rendered.contains("OK WIFI detail=subcommand=diag"),
            "{rendered}"
        );
    }

