    #[cfg(feature = "kernel")]
    #[test]
    fn wifi_diagnostics_preserve_cause_and_report_distinct_recovery_fault() {
        let causal = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-firmware-release",
            op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_RELEASE,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            control_cmd: 0,
            control_id: 0,
            control_header_mode: "not-control",
            control_response_len: 0,
            detail: 0x532a,
            reason: "cyw43-post-release-ht-clock",
            result: 0x50,
        };
        let recovery = crate::drivers::driver_task_net::Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-transport-init",
            op: pi4_driver_abi::DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            detail: 0x5310,
            reason: "cyw43-transport-bus-link-missing",
            result: 0,
            ..causal
        };

        assert_eq!(
            KernelConsoleTestPump::wifi_recovery_fault_after_causal(Some(causal), Some(recovery)),
            Some(recovery)
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_recovery_fault_after_causal(Some(causal), Some(causal)),
            None
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_partition_runtime_faults(
                None,
                Some(recovery),
                false,
                false,
            ),
            (Some(recovery), None),
            "without retained evidence the latest fault is the primary cause",
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_partition_runtime_faults(None, Some(recovery), true, false,),
            (None, Some(recovery)),
            "retained deferred/terminal evidence keeps the later fault secondary",
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_partition_runtime_faults(None, Some(recovery), true, true,),
            (None, None),
            "the retained record already owns a field-matched latest terminal",
        );
        assert_eq!(
            KernelConsoleTestPump::wifi_partition_runtime_faults(
                Some(causal),
                Some(recovery),
                false,
                false,
            ),
            (Some(causal), Some(recovery)),
        );
    }

